#include "paired_ridge.hpp"
#include <iostream>
using namespace semes;
int wmain(int argc,wchar_t** wide){Utf8Arguments args(argc,wide);auto argv=args.data();try{if(argc!=3)throw std::runtime_error("paired_ridge training.json new-output");auto j=Json::parse(read(fs::u8path(argv[1])));fs::path out=fs::u8path(argv[2]);if(fs::exists(out))throw std::runtime_error("New output required");std::vector<std::string> dates;for(const auto& value:j.at("dates").array)dates.push_back(value.str());const auto& config=j.at("config");PairedRidge model(config.at("alpha").num(),config.at("pair_weight").num(),config.has("repeat_weight")?config.at("repeat_weight").num():0);auto X=matrix(j.at("X"));model.fit(X,matrix(j.at("commands")),dates);auto result=model.json();result["prediction"]=jsonmatrix(model.predict(j.has("test_X")?matrix(j.at("test_X")):X));write(out/"model.json",result.dump());std::cout<<"Native paired model trained\n";return 0;}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
